abstract class AbstractCompiler {
    protected abstract CompilerOptions createOptions();
    protected abstract SourceFile[] loadLibraryFiles(CompilerOptions options);
    public abstract void process(SourceFile externs[], SourceFile inputs[], CompilerPass... passes);
    public abstract Node parseInputs();
    public abstract void parse();
    public abstract JSError[] getErrors();
    public abstract JSError[] getWarnings();
    public abstract boolean hasErrors();
    public abstract void report(JSError error);
    public abstract void setLifeCycleStage(LifeCycleStage stage);
    public abstract LifeCycleStage getLifeCycleStage();
    public abstract CodingConvention getCodingConvention();
    public abstract Node getRoot();
    public abstract void reassessNodeOrder();
    public abstract JSModuleGraph getModuleGraph();
    public abstract String getSourceLine(Node n);
    public abstract SourceMap generateSourceMap();
    public CompilerInput newCompilerInput(String code) {
        return new StringCompilerInput(code);
    }
     public enum LifeCycleStage {
        NORMALIZED_PROCESSED
    }
}

