// Mock IR for creating nodes. In a real scenario, this would be part of Rhino or Closure compiler.
class IR {
    static Node newNode(int type) { return new Node(type); }
    static Node newNode(int type, double value) { Node n = new Node(type); n.setDouble(value); return n;}
    static Node newNode(int type, String value) { Node n = new Node(type); n.setString(value); return n;}
    static Node name(String name) { Node n = newNode(Token.NAME); n.setString(name); return n; }
    static Node getprop(Node obj, String prop) { Node n = newNode(Token.GETPROP); n.addChildToBack(obj); n.addChildToBack(newNode(Token.STRING, prop)); return n; }
    static Node call(Node fn, Node... args) { Node n = newNode(Token.CALL); n.addChildToBack(fn); for (Node arg : args) n.addChildToBack(arg); return n; }
    static Node param(String name) { Node n = newNode(Token.PARAM); n.setString(name); return n; }
    static Node paramList(Node... params) { Node n = newNode(Token.LP); for (Node p : params) n.addChildToBack(p); return n; }
    static Node block(Node... statements) { Node n = newNode(Token.BLOCK); for (Node s : statements) n.addChildToBack(s); return n; }
    static Node returnNode(Node expr) { Node n = newNode(Token.RETURN); n.addChildToBack(expr); return n; }
    static Node returnNode(Node expr, int lineno, int charno) { Node n = new Node(Token.RETURN, expr, lineno, charno); return n; }
    static Node number(double value) { return newNode(Token.NUMBER, value); }
    static Node add(Node left, Node right) { Node n = newNode(Token.ADD); n.addChildToBack(left); n.addChildToBack(right); return n; }
    static Node exprResult(Node expr) { Node n = newNode(Token.EXPR_RESULT); n.addChildToBack(expr); return n;}
    static Node assign(Node lhs, Node rhs) { Node n = newNode(Token.ASSIGN); n.addChildToBack(lhs); n.addChildToBack(rhs); return n; }
    static Node var(String name, Node value) { Node n = newNode(Token.VAR); n.addChildToBack(newNode(Token.NAME, name)); if (value != null) n.getChildAtIndex(0).addChildToBack(value); return n; }
    static Node script(Node... statements) { Node n = newNode(Token.SCRIPT); for (Node s : statements) n.addChildToBack(s); return n; }
    static Node ifNode(Node condition, Node thenBranch, Node elseBranch) { Node n = newNode(Token.IF); n.addChildToBack(condition); n.addChildToBack(thenBranch); if (elseBranch != null) n.addChildToBack(elseBranch); return n;}
    static Node booleanNode(boolean value) { return newNode(Token.TRUE); } // Simplified, a real boolean node would have type and value
    static Node ternary(Node condition, Node thenBranch, Node elseBranch) { Node n = newNode(Token.HOOK); n.addChildToBack(condition); n.addChildToBack(thenBranch); n.addChildToBack(elseBranch); return n; }
    static Node function(String name, Node params, Node body) { Node n = newNode(Token.FUNCTION); n.addChildToBack(newNode(Token.NAME, name)); n.addChildToBack(params); n.addChildToBack(body); return n; }
    static Node name(String name, int lineno, int charno) { return new Node(Token.NAME, name, lineno, charno); }
    static Node newNumber(double value) { return newNode(Token.NUMBER, value); }
    static Node newExpr(Node child) { return NodeUtil.newExpr(child); }
    static Node newUndefinedNode(Node srcLocation) { Node n = new Node(Token.NAME); n.setString("undefined"); return n;}
}

